#!/usr/bin/env bash
# Runs the `product` step of .github/workflows/custom.yml, as written in the workflow, against fixtures.
#   <name>@<version>[+arc].json  product output, byte for byte, generated by
#                                dagger-container-builds@0.4.1 builds/custom.ProductJson
#   <name>.buildargs.json        build args per entry, as builds/custom.BuildContainer selected them,
#                                compared as one object per entry (later keys win)
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
fixtures=$root/test/fixtures/custom
step=$(yq '.jobs.product.steps[] | select(.id == "product") | .run' "$root/.github/workflows/custom.yml")
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

pass=0
fail=0

# run_step <config> <version> <arc_hosts>; prints the GITHUB_OUTPUT file path
run_step() {
  local dir=$work/$RANDOM
  mkdir -p "$dir"
  cp "$1" "$dir/config.yaml"
  : > "$dir/out"
  (cd "$dir" && CONFIG=config.yaml VERSION=$2 ARC=auto ARC_LABEL=arc-arm64 ARC_HOSTS=$3 GITHUB_OUTPUT=$dir/out \
    bash -c "$step" > /dev/null)
  echo "$dir/out"
}

check() {
  if [ "$2" = "$3" ]; then
    pass=$((pass + 1))
    echo "ok   $1"
  else
    fail=$((fail + 1))
    echo "FAIL $1"
    diff <(printf '%s\n' "$2") <(printf '%s\n' "$3") || true
  fi
}

for expected in "$fixtures"/*@*.json; do
  base=$(basename "$expected" .json)
  name=${base%@*}
  rest=${base#*@}
  version=${rest%+arc}
  arc_hosts=''
  [ "$rest" != "$version" ] && arc_hosts=mac-a
  out=$(run_step "$fixtures/$name.yaml" "$version" "$arc_hosts")
  check "product $base" "$(cat "$expected")" "$(sed -n 's/^product=//p' "$out")"
done

for expected in "$fixtures"/*.buildargs.json; do
  base=$(basename "$expected" .json)
  name=${base%.buildargs}
  out=$(run_step "$fixtures/$name.yaml" latest '')
  actual=$(sed -n 's/^build_args=//p' "$out" \
    | jq -cS 'map(reduce (.[] | capture("^(?<k>[^=]*)=(?<v>.*)$"; "s")) as $a ({}; .[$a.k] = $a.v))')
  check "build_args $base" "$(jq -cS . "$expected")" "$actual"
done

echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
